    baby_patches = image_patch.find("baby")
    toy_patches = image_patch.find("toy")

    if not baby_patches or not toy_patches:
        return image_patch

    baby_centers = [(p.horizontal_center, p.vertical_center) for p in baby_patches]
    toy_centers = [(p.horizontal_center, p.vertical_center) for p in toy_patches]

    baby_toy_distances = [(b, t, math.sqrt((b[0] - t[0])**2 + (b[1] - t[1])**2)) for b in baby_centers for t in toy_centers]

    closest_distance = min(baby_toy_distances, key=lambda x: x[2])

    for baby_patch in baby_patches:
        if (baby_patch.horizontal_center, baby_patch.vertical_center) == closest_distance[0]:
            return baby_patch

