def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    gal_patches = image_patch.find("gal")
    shirt_patches = image_patch.find("shirt")

    if not gal_patches or not shirt_patches:
        return image_patch

    gal_center_x = sum(p.left + (p.right - p.left) // 2 for p in gal_patches) / len(gal_patches)
    shirt_center_x = sum(p.left + (p.right - p.left) // 2 for p in shirt_patches) / len(shirt_patches)

    gal_patches_right = [g for g in gal_patches if g.left + (g.right - g.left) // 2 > gal_center_x]
    shirt_patches_left = [s for s in shirt_patches if s.right < gal_center_x]

    if not gal_patches_right or not shirt_patches_left:
        return image_patch

    best_match = None
    min_distance = float('inf')

    for gal in gal_patches_right:
        for shirt in shirt_patches_left:
            if gal.color == "gray":
                dist = abs(gal.left - shirt.right)
                if dist < min_distance:
                    min_distance = dist
                    best_match = gal

    return best_match

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    backpack_patches = image_patch.find("backpack")

    if not man_patches or not backpack_patches:
        return image_patch

    man_patches.sort(key=lambda p: abs(p.left - image.shape[1] // 2))

    man_on_left = [m for m in man_patches if m.right < image.shape[1] // 2]
    man_second_from_left = man_on_left[1] if len(man_on_left) >= 2 else man_on_left[0]

    for man in man_patches:
        if man == man_second_from_left:
            continue

        man_rect = (man.left, man.lower, man.right, man.upper)
        for bp in backpack_patches:
            if not bp.overlaps_with(*man_rect):
                return man_second_from_left

    return man_second_from_left

