ImagePatch.prototype.distance_to_center = function() {
    let centerX = Math.round(this.left + (this.right - this.left) / 2);
    let centerY = Math.round(this.lower + (this.upper - this.lower) / 2);
    return Math.sqrt(centerX * centerX + centerY * centerY);
};

